module sum_of_maxes (\n    input clk,\n    input rst_n,\n    input start,\n    input [3:0] N,\n    input [3:0] K,\n    input [511:0] values_packed,\n    output reg [31:0] result,\n    output reg done\n);\n\n// Module parameters\nlocalparam [31:0] MOD = 32'd1000000007;\nlocalparam [3:0] IDLE       = 4'd0;\nlocalparam [3:0] LOAD       = 4'd1;\nlocalparam [3:0] SORT_INIT  = 4'd2;\nlocalparam [3:0] SORT_LOOP  = 4'd3;\nlocalparam [3:0] COMPUTE    = 4'd4;\nlocalparam [3:0] REDUCE     = 4'd5;\nlocalparam [3:0] FINISH     = 4'd6;\n\n// State registers\nreg [3:0] state, next_state;\n\n// Data registers\nreg [31:0] data_reg [0:15];\nreg [31:0] sorted [0:15];  // Sorted version (ascending)\n\n// Combinatorial logic\nreg [63:0] accumulator;\nreg [3:0] sort_i, sort_j;\nreg [3:0] comp_idx;\nreg [7:0] cycles;\ninteger i;\n\n// Binomial coefficient table\nreg [31:0] binom_table [0:15][0:15];\n\n// FSM main control\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        // Initialize all registers\n        state <= IDLE;\n        done <= 1'b0;\n        result <= 32'd0;\n        accumulator <= 64'd0;\n        sort_i <= 4'd0;\n        sort_j <= 4'd0;\n        comp_idx <= 4'd0;\n        cycles <= 8'd0;\n        for (i = 0; i < 16; i = i + 1) begin\n            data_reg[i] <= 32'd0;\n            sorted[i] <= 32'd0;\n        end\n    end else begin\n        state <= next_state;\n        cycles <= cycles + 8'd1;\n\n        case (state)\n            LOAD: begin\n                // Unpack values from 512-bit input\n                for (i = 0; i < 16; i = i + 1) begin\n                    data_reg[i] <= values_packed[i*32 +: 32];\n                end\n            end\n\n            SORT_INIT: begin\n                // Copy to sorted array\n                for (i = 0; i < 16; i = i + 1) begin\n                    sorted[i] <= data_reg[i];\n                end\n                sort_i <= 4'd1;\n                sort_j <= 4'd0;\n            end\n\n            SORT_LOOP: begin\n                // Bubble sort implementation\n                if (sorted[sort_j] > sorted[sort_j+1]) begin\n                    // Swap elements\n                    sorted[sort_j] <= sorted[sort_j+1];\n                    sorted[sort_j+1] <= sorted[sort_j];\n                end\n\n                if (sort_j < (N - sort_i)) begin\n                    sort_j <= sort_j + 4'd1;\n                end else begin\n                    sort_i <= sort_i + 4'd1;\n                    sort_j <= 4'd0;\n                end\n            end\n\n            COMPUTE: begin\n                if (comp_idx >= (N - K)) begin\n                    // Multiply by binom(N - 1 - idx, K - 1)\n                    accumulator <= accumulator + (\n                        sorted[comp_idx] * binom_table[N - 1 - comp_idx][K - 1]\n                    );\n                end\n                comp_idx <= comp_idx + 4'd1;\n            end\n\n            REDUCE: begin\n                if (accumulator >= MOD) begin\n                    accumulator <= accumulator - MOD;\n                end\n            end\n\n            FINISH: begin\n                result <= accumulator[31:0];\n                done <= 1'b1;\n            end\n\n            IDLE: begin\n                done <= 1'b0;\n            end\n        endcase\n    end\nend\n\n// Next state logic\nalways @(*) begin\n    next_state = state;\n    case (state)\n        IDLE:   if (start) next_state = LOAD;\n\n        LOAD:   next_state = (N == 4'd1) ? COMPUTE : SORT_INIT;\n\n        SORT_INIT: next_state = SORT_LOOP;\n\n        SORT_LOOP: begin\n            if (sort_i >= N) next_state = COMPUTE;\n            else if (sort_j < (N - sort_i)) next_state = SORT_LOOP;\n            else next_state = SORT_LOOP;  // Continue next iteration\n        end\n\n        COMPUTE: begin\n            if (comp_idx < N) next_state = COMPUTE;\n            else next_state = REDUCE;\n        end\n\n        REDUCE: begin\n            if (accumulator < MOD) next_state = FINISH;\n            else next_state = REDUCE;\n        end\n\n        FINISH: next_state = IDLE;\n\n        default: next_state = IDLE;\n    endcase\nend\n\n// Binomial coefficient table precomputation\ninitial begin\n    for (i = 0; i < 16; i = i + 1) begin\n        for (j = 0; j < 16; j = j + 1) begin\n            if (j == 0) binom_table[i][j] = 32'd1;\n            else if (j > i) binom_table[i][j] = 32'd0;\n            else binom_table[i][j] = (binom_table[i-1][j-1] + binom_table[i-1][j]) % MOD;\n        end\n    end\nend\n\nendmodule